
pfQuest_questcache = {
	["Keep An Eye Out:42:Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.:Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?"] = {
		[1] = 576,
	},
	["Rise of the Silithid:49:Take the Insect Analysis Report to Gracina Spiritmight in Darnassus.:I urge you to take this report to someone who has working knowledge in this kind of thing.\n\nI know this night elf scholar named Gracina Spiritmight.  She's spent a lot of time studying life forms that are unique to the ecology of Azeroth; she's a historian to boot!  If you want someone to help figure out what exactly this threat is, and more importantly how to stop it, give her the report.  We'll need the help.\n\nLast I heard, she was residing in the Temple of the Moon, located in Darnassus."] = {
		[1] = 162,
	},
	["The Prophecy of Mosh'aru:47:Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.:The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence.  It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.\n\nBring me the Mosh'aru tablets!\n\nThe first tablet is held by the long-dead troll Theka the Martyr.  It is said his persecutors were cursed into scarabs and now scuttle about his shrine.\n\nThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.\n\nWhen you have the tablets, bring them to me."] = {
		[1] = 3527,
	},
	["The Caravan Road:30:Speak with Clerk Daltry in Darkshire.:Turns out I was wrong about you, and that isn't something that happens everyday.\n\nIt just so happens that I remember this Velinde you're looking for. Isn't every day that a night elf priestess that wants to travel with a dirty old--but great for your shipping needs!--caravan like my own.\n\nWe split up on the way north, she was headed for Darkshire. The clerk there keeps all sorts of records. Might know something useful.\n\nBe careful in the jungle, it is a deadly place even at the best of times."] = {
		[1] = 1041,
	},
	["Patrol Schedules:37:Speak with Corporal Sethman.:The note you gave me is signed with an \"-M\"...I don't know what that could mean.\n\nBut...the note also says this person shared patrol routes with Thorsen last week.  So whoever shared patrol with Thorsen last week must be the traitor!\n\nGo to Corporal Sethman.  He handles the patrol schedules and can tell you who was with Thorsen."] = {
		[1] = 330,
	},
	["The Giant Guardian:49:Locate the lost night elf girl.:I am no good, Ewwor. I was 'spose to be watchin' over my little friend, Shay, and somehow, she got away from me. I'm not all that sure what happened, really, but last time I saw her, we was walkin' through the ruins just north of here.\n\nEverythin' was goin' fine, but then I turned around, and... she was gone.\n\nNow I jus can't quite figure out what I should do here. Got any ideas, Ewwor? I'm awful worried.\n\nHey, how 'bout you go look fer Shay? Yer legs can travel much faster 'n mine."] = {
		[1] = 2844,
	},
	["The Deserters:38:Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.:It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe deserters' leader is a man named Jacken. See if you can get some information out of him.\n\nBe warned, Ewwor. He may be a tough nut to crack."] = {
		[1] = 1286,
	},
	["The High Wilderness:44:Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes.:Although it is dangerous, Troyas and I have been investigating the ruins that cover the forests of Feralas.\n\nLately, though, Troyas has been going on his own to the High Wilderness, and I really worry about him. The Gordunni Ogres have taken over that area, and they don't take kindly to anyone that enters their territory.\n\nI was hoping you might be willing to travel to the ruins to the southeast and clear out some of the ogres. Make it a little safer for my Troyas, and I will be extremely grateful."] = {
		[1] = 2982,
	},
	["Fire and Brimstone:60:Defeat Ragnaros, the Firelord.:Ragnaros has been reawakened by Sorcerer-Thane Thaurissan and now threatens to reduce Azeroth to ashes. Prepare yourself, Daidinn, for your first trial is by fire. Head down to the very depths of Molten Core and defeat Ragnaros, the Firelord. \n\nTo say that this isn’t an easy task would be a major understatement. You must be prepared! Gather any help you can muster, either from the ranks of the Companions or anyone else who is foolish enough to join you on this perilous endeavor. Molten Core is one of the hottest places in Blackrock Mountain so make sure to bring plenty of fire resistance equipment and aqual dousers. \n\nShould you succeed, you will not only have saved our world, but this will also elevate you in our ranks. Make haste, Daidinn, for the scorched earth is spreading by the day and soon enough there won't be anything left to save.\n"] = {
		[1] = 10034,
	},
	["The Haunted Isle:37:Speak with Baron Revilgaz in Booty Bay.:Baron Revilgaz has had me keep an ear out for rumors of the strange and out-of-place in Booty Bay and Stranglethorn. I don't usually put much stock in ghost stories, but I heard some sailors in the tavern talking about a haunted island off the coast. Water elementals and a raving goblin ghost, they say.\n\nIf you're going to go talk to Revilgaz, could you relay that story to him?"] = {
		[1] = 616,
	},
	["A Hero's Welcome:46:Speak with Shandris Feathermoon in Feathermoon Stronghold.:Ewwor, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least.\n\nGeneral Feathermoon is waiting for you in the main compound."] = {
		[1] = 4266,
	},
	["Moonglow Vest:18:Bring 1 Embossed Leather Glove, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.:We in Darnassus, especially we craftsman, are quite busy.  Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies.\n\nIf you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique."] = {
		[1] = 1582,
	},
	["Egg Freezing:60:Use the Eggscilloscope Prototype on an egg in the Rookery.:Daidinn, I've been working hard on a new device, the eggscilloscope!  It's designed to project a burst of cold energy at the egg of a black dragon... and freeze it solid!  Can you test it for me?\n\nI heard that high up in Blackrock Spire, the dragons have a rookery where they hatch their eggs.  That's where you'll have to go to test the eggscilloscope, and then let me know how it worked!\n\nAnd don't worry.  Frozen dragon eggs should be harmless.  It's the unfrozen ones you have to worry about!"] = {
		[1] = 4734,
	},
	["Chapter II:40:Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.:Chapter II was chock full of exciting tales of panther and tiger hunting.  I could just kick myself for letting the pages blow away! \n\n It seems I was able to recover all of the pages with the exception of pages 10, 11, 14, and 16."] = {
		[1] = 340,
	},
	["The Bloodsail Buccaneers:41:Report your findings to First Mate Crazz in Booty Bay.:The map shows Booty Bay with a red \"X\" drawn precisely at the spot at which you are standing.\n\nThe scribbled text reads:\n\n\"You men are to secure a camp at this location and keep quiet.  Wait for the signal from the southern command post before attacking.  If anyone approaches you, kill them.\""] = {
		[1] = 597,
	},
	["Kurzen's Mystery:38:Find the 4 tablets and bring their legends back to Brother Nimetz.:Colonel Kurzen was once a great, noble man - I must find what caused his fall into depravity!  He may be under the sway of troll magic.  To confirm this, I must study some of their legends.\n\nThere are 4 tablets hidden within the troll ruins of Stranglethorn.  I must see what is written on these tablets!  Transcribe their markings and bring the transcriptions back to me.\n\nThe first tablet is in the Bal'lal Ruins, the second is in the Vile Reef, and the third and fourth are in the Ruins of Zul'Kunda."] = {
		[1] = 207,
	},
	["Whiskey Slim's Lost Grog:50:Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.:We was splicin' the mainbrace somethin' fierce off of the Overlook Cliffs, ol' Hinterlands just in the distance.  Thought the seas was goin' to swallow us whole.\n\nOl' Slim knows all about liquid courage!  Cap'n had a crate of Pupellyverbos Port we commandeered from a privateer en route to Stormwind.\n\nSo when that storm off of Hinterlands hit, I busted into the grog.  Big wave hit and tossed them bottles overboard.  Cap'n is goin' to give me a taste o' the cat if ye don't help me get 'em back though!"] = {
		[1] = 580,
	},
	["Akiris by the Bundle:43:Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.:Ewwor, since I have you here, I got a message from Groy while you were gone. He mentioned bein' satisfied with the last shipment that arrived and has a client that wants some more of the stuff right away.\n\nI won't be headin' to Theramore for a week, but if you're willin' to make the journey, there's no reason you can't take the stuff for me.\n\nFeeling adventurous? You do know where Dustwallow Marsh is, doncha? I'd be careful though, Theramore can be dangerous if you're the wrong kind of crowd."] = {
		[1] = 623,
	},
	["Favored of Elune?:47:Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village.:Wildkin are quite unpredictable creatures, Ewwor. Capable of incredible gentleness, these creatures will show extreme ferocity if something they deem important is threatened.\n\nThese beasts are rumored to have been created by Elune, and I am interested in finding if this is really the truth.\n\nRecently, I heard about a population of wildkin living in the Hinterlands -- Vicious, Primitive, and Savage Owlbeasts. They can be found amongst the wildlife there. Will you gather some wildkin feathers for me?"] = {
		[1] = 3661,
	},
	["Chapter IV:40:Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.:Ah Chapter IV; the big finale!  And what an ending it was! \n\nWe are only missing three pages for this chapter.  We need pages 25, 26 and 27 to put Chapter IV back together."] = {
		[1] = 342,
	},
	["Raptor Mastery:41:Hemet Nesingwary wants you to kill 10 Jungle Stalkers.:Let's see how you handle this next challenge.  There is a cagey breed of raptor out there.  We call them Jungle Stalkers.  They are far more difficult to track down and kill than the other breeds you've been trying your luck at.  Kill 10 Jungle Stalkers and I'll tip you off to the best hunting yet."] = {
		[1] = 196,
	},
	["The Black Shield:35:Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.:An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney."] = {
		[1] = 1253,
	},
	["Panther Mastery:33:Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers.:Now you're ready to turn it up a notch.  If you want to prove yourself worthy of socializing with the likes of these big game hunters, you'll need to prove that you can kill 10 panthers.\n\nThose big boys are tougher.  They're not as easy as the young ones you were killing earlier."] = {
		[1] = 191,
	},
	["The Green Hills of Stranglethorn:40:Collect the missing pages from The Green Hills of Stranglethorn manuscript.  Once all four chapters are complete, return them to Barnil.:Master Nesingwary will be so upset if he finds out!\n\nHe trusted me to proofread the manuscript of his novel, The Green Hills of Stranglethorn.  Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere!\n\nI was able to gather most of the pages but many are still strewn about the jungle.  Collect the pages to complete each of the four chapters.\n\nI will help you organize them.  Return the chapters to me once you have all four."] = {
		[1] = 338,
	},
	["The Bait for Lar'korwi:56:Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.:This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains. It was here I saw Lar'korwi last. You will know you are in the right area because of all the bones from massive creatures that once wandered nearby. Take the meat you recovered and place it there. Then, rub this mixture I created on the meat. If both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will."] = {
		[1] = 4292,
	},
	["Tran'rek:45:Speak with Tran'rek in Gadgetzan.:My cousin Tran'rek is in a tight spot.  He promised me a load of scarab shells weeks ago and he hasn't delivered.  He's my cousin, so I'd hate to have to send someone to Gadgetzan to break something on him.\n\nCan you speak to Tran'rek for me?  Let him know he needs to get that delivery together before I do something rash?\n\nGadgetzan is in northern Tanaris, in Kalimdor."] = {
		[1] = 2864,
	},
	["Water Pouch Bounty:44:Bring 5 Wastewander Water Pouches to Spigot Operator Luglunket in Gadgetzan.:Greetings Ewwor - the name's Luglunket, and we've got an important job for you if you're up for it!  Huzzah!\n\nNothing would please me more as a seasoned spigot operator to take any Wastewander water pouches you might find out in the desert.  That's our water anyway - the nomads have just stolen it is all!  The Gadgetzan Water Company will offer you an official care package for every five you turn in.  Most importantly though, you're helping Gadgetzan help itself!"] = {
		[1] = 1707,
	},
	["Troll Necklace Bounty:45:Bring 5 Troll Tribal Necklaces to Fraggar Thundermantle in Aerie Peak.:Get this straight, night elf - we are NOT part of the Alliance!  The Wildhammers are independent, relying on deeds and actions to prove one's worth, rather than the blather of those who use jibber-jabber to bolster their do-nothing attitudes!\n\nIf you're looking for friends here, then prove your worth to us first!  The foul trolls that choke the hillsides of the Hinterlands sometimes carry tribal necklaces.  Bring five of them to me, and we'll mark it down as a step in the right direction for you."] = {
		[1] = 2880,
	},
	["Thalanaar Delivery:44:Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.:This parcel of goods you found in the Woodpaw gnoll camps was supposed to be delivered to the small way-station of Thalanaar in southeastern Feralas.  Regardless of the missing courier's fate, the task of delivering the parcel remains unfinished.\n\nExamining the parcel in detail reveals a hand written name of \"Falfindel Waywarder\" on the outside of the packaging.  Perhaps this is the parcel's ultimate recipient."] = {
		[1] = 4281,
	},
	["Panther Mastery:38:Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers.:Now the hard part.  A true panther hunter can show skill by dropping Shadowmaw Panthers, the deadliest in Stranglethorn.  Prove to us that you can slay 10 of these beasts.\n\nIf you think they are hard to track, wait until you attempt to slay one...."] = {
		[1] = 192,
	},
	["March of the Silithid:53:Speak to Alchemist Pestlezugg in Gadgetzan.:It would seem that the silithid's intent, nay - reason for being, is to devour everything in their path that is not of their ecology.  Their focus is singular, and it is for this reason they are a grave threat to all life on Azeroth.\n\nWhat we've seen to date is but the first stages.  I suspect that their strength comes from deeper in Kalimdor: Un'Goro Crater.  Go to Gadgetzan in the Tanaris desert and speak to Alchemist Pestlezugg.  Tell him of my theory; he will surely aid us in fighting the silithid."] = {
		[1] = 4493,
		[2] = 4494,
	},
	["Dungeon Licence : T3D:60:Meet the requirements for obtaining a Tier 3 Dungeon Licence.:When the opportunity arises we must take advantage of it, Daidinn. Tougher enemies usually means better gear and a chance for us to scavenge for useful items in the aftermath of battle. But it does not always come down to fighting. Many in our ranks are not fighters, but crafters, gatherers, artisans, illusionists and so on, of various backgrounds and interests. Their skills and abilities are the engine that keeps our organization moving. \n\nWe value those who know how to forge a sword just as much as those who know how to wield it, and even more so those who know how to do both! Expand your horizons, Daidinn, and pick up a profession or ten. You never know what kind of gadgets you may come up with that could turn the tide of a battle. The basic professions we encourage all our members to learn are First Aid and Cooking. These will allow you to become self-sufficient. Besides, nobody wants to fight on an empty stomach. \n"] = {
		[1] = 10022,
	},
	["Excelsior:38:Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.:With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder saltwater crocolisk. The elders only come out to defend the other saltwater crocs, so you might need to kill a few to draw one out."] = {
		[1] = 628,
	},
	["Some Assembly Required:36:Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.:Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out."] = {
		[1] = 577,
	},
	["Answered Questions:30:Return to Thyn'tel Bladeweaver in Darnassus.:We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions. Strange events are afoot in these times, Ewwor, and the darkness knows no respite.\n\nI will keep you no longer. I suspect that there are others that should hear of what you have found in the mines of Duskwood."] = {
		[1] = 1044,
	},
	["Reclaiming the Charred Vale:27:Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.:The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken.\n\nFar south of the Barrens lies a land known as Thousand Needles. If you travel west in Thousand Needles until you reach the lush forest's edge of Feralas, you will find a druid named Falfindel Waywarder.\n\nThis great and wise druid is capable of calling forth great forest spirits which can aid in the reclamation of the Charred Vale.\n\nSend word of our need! Seek him out at once!"] = {
		[1] = 1059,
	},
	["Tiger Mastery:35:Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers.:Now I'm going to up the stakes on you and truly test your skill.  Prove to me you can kill 10 Elder Stranglethorn Tigers.  If you can do that, you will be ready for your final challenge before I declare you a master tiger hunter in Master Nesingwary's presence.\n\nElder Stranglethorn Tigers are not only the most difficult to find, they are also the fiercest to defeat."] = {
		[1] = 187,
	},
	["Venture Company Mining:41:Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.:The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!  Please, you must help me!\n\nThe Venture Company is mining near the Crystalvein Mine to the north.  They can't get into the mine because of all the basilisks, but they're still able to dig up Singing Crystals from the surrounding hills.\n\nTake their crystals from them, and show them they don't have the run of the jungle.\n\nAnd... um... bring me those crystals as proof!"] = {
		[1] = 600,
	},
	["More Wastewander Justice:44:Take down 10 Wastewander Shadow Mages, 8 Wastewander Rogues, and 6 Wastewander Assassins for Chief Engineer Bilgewhizzle in Gadgetzan.\n:We need you to take on the stronger ranks of the Wastewander nomads now.  You've done a good job thus far, but if we are to take back those water wells, then it only makes sense to do it against as few nomads as possible!\n\nThis time around we need you to take down their rogues, assassins, and shadow mages.  You'll find them east and southeast of here.\n\nI'm not going to lie to you - they're a nasty lot.  Do this for us though, and we'll be on our way to taking back what is rightfully ours!"] = {
		[1] = 1691,
	},
	["Noxious Lair Investigation:47:Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.:All right now, these reports about the bugs... what we know is that they are draining the water pools that used to be where the Noxious Lair is. What we DON'T know is, well, everything else.\n\nLet's figure out who our enemy is first! I want you to head into the Noxious Lair and get some parts off of those critters. Get five from the Centipaar there and bring them to Alchemist Pestlezugg for him to dink with. With him on the case, we'll figure out what they are!"] = {
		[1] = 82,
	},
	["The Hidden Key:37:Use the Small Brass Key to open Bookie Herod's Strongbox.:Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key.\n\nAnd after further study of his notes, a few references to a \"secure strongbox\" are contained among various papers.  The box is somewhere within the Stockpile - the cavern complex at the back of Kurzen's Compound.\n\nIf this secure strongbox is found, and the small brass key can open it, then perhaps the mystery behind Thorsen's detection will be revealed."] = {
		[1] = 328,
	},
	["The Northern Pylon:53:Discover the location of the Northern Crystal Pylon in Un'Goro Crater.:What could they be for? I can't get the thought out of my head!\n\nIt's driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I'll usually believe anything people tell me.\n\nAnyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, Ewwor. I just know they exist."] = {
		[1] = 4285,
	},
	["Favor for Krazek:37:Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.:There is a mountain cave in Drywhisker Gorge, far to the north in the Arathi Highlands.  In that cave is rare ore: bloodstone.  The bloodstone in this cave is not of the highest grade, but even low-quality bloodstone is valuable... to those with the knowledge to use it.\n\nI would like some.\n\nI will fix your crock pot, but while I work on it... bring me samples of bloodstone.  Bring me enough, and I'll even give you a bonus.\n\nOh, and if you don't have the skill to mine it... find someone who does!"] = {
		[1] = 627,
	},
	["Raptor Mastery:36:Hemet Nesingwary wants you to kill 10 Lashtail Raptors.:Now let's step up the challenge and see if you're up to it.  Venture into the jungle and bag yourself 10 of those bloody Lashtail Raptors.  Let's see what you've got!"] = {
		[1] = 195,
	},
	["Bloodscalp Ears:35:Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.:Damn trolls! They've been killing off our agents in the jungle! I've already lost a good number of my best guards to skirmishes with them. The costs are piling up! How will I explain this to Baron Revilgaz?\n\nDecisive action... Think, Kebok... you weren't assigned to the post you have today for sitting around... I've got it! You... Ewwor, is it? You'll help me, won't you? There's money to be had!\n\nHere's the deal... you bring me the ears of fifteen Bloodscalp Trolls, and I'll compensate you well."] = {
		[1] = 189,
	},
	["The Scythe of Elune:30:Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.:Your story rings true... I do not entirely understand your motives, but if your business here in Duskwood involves ridding the forest of worgen in any number, then I can forgo understanding for results.\n\nThere is a mine to the south that has been overrun with worgen... They appeared out of nowhere, but from what we know, that is where they first were found.\n\nGo about your business, but I would ask that if you find anything of import, you share it with me. We will accept any aid in our war against evil."] = {
		[1] = 1043,
	},
	["Jammal'an the Prophet:53:The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.:My Witherbark companions don't take kindly to strangers around their home.\n\nMe? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows.\n\nOur spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality.\n\nBut I urged caution. What if the prophecy was nothing more than manipulation?\n\nI want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be free."] = {
		[1] = 1446,
	},
	["Doomrigger's Clasp:60:Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.:There is a chamber, high in Blackrock Spire, that was once called the Hall of Fortune.  It was where the Dark Iron dwarves kept their relics, trophies and objects of art.\n\nThat was long ago.  It is said the hall has collapsed and is now used for... less savory tasks.  But I believe some old dwarven relics may still be found there.\n\nOne such relic is Doomrigger's clasp, with a surface so encrusted with rare gems that it was said to make weep any dwarf who gazes upon it.\n\nThat clasp, Daidinn, is your goal."] = {
		[1] = 4764,
	},
	["Pirate Hats Ahoy!:45:Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.:You're the help the Cartel sent? I suppose you'll do. Listen carefully druid. As you know, I am a procurer of fashionable apparel for the elite of Azerothian society.  Kings and Queens, Warchiefs and, well whatever the Horde calls their queens, all wear what I choose is in style.  And they pay through the nose for it, which is the best part.\n\nSo here's what's going to happen. You head down to Lost Rigger Cove and acquire a lot of pirate hats by whatever means. Do you think you can handle that?"] = {
		[1] = 8365,
	},
	["Cracking Maury's Foot:44:Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.:Curses!  That swab Maury put a lock on his foot, and I can't open it!  His loot's inside the foot, and that's what he owes me!\n\nWe need to find the key to open the lock.  Maury was known to gamble with the Mosh'Ogg ogres, at their mound to the northeast.  And he told me, when he was still alive, that the last time he went to the mound he was chased off after winning too much.  Maybe the Ogres there have his key.\n\nBut if they do, you might have to kill a load of them to find the right one..."] = {
		[1] = 613,
	},
	["The Western Pylon:53:Discover the location of the Western Crystal Pylon.:My experiments so far have not yielded any positive results, Ewwor. I can't help but hope that you can find a solution by searching for one of the pylons that I have heard exist.\n\nPerhaps if we combine certain colors at them... but I get ahead of myself. Let's find them first!\n\nEwwor, search the western area of the crater; a pylon is said to be somewhere in that area."] = {
		[1] = 4288,
	},
	["The Monogrammed Sash:50:Return the Monogrammed Sash to its owner.:This fine sash has the letters \"HS\" embroidered along its hem."] = {
		[1] = 8552,
	},
	["Deliver to MacKinley:45:Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay.:Thanks again for your help, Ewwor.  Here's a bottle of Steamwheedle bilge rum.  Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze."] = {
		[1] = 2874,
	},
	["Gizelton Caravan:38:Escort the Gizelton Caravan through Mannoroc Coven. Talk with Smeed at Scrabblescrew's Camp for your reward.:You look like a capable night elf. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!\n\nUp ahead is Mannoroc Coven... normally the demons ignore us but something has the kodos spooked this time. I'll pay you to protect the caravan past Mannoroc Coven. Once we are safely past you can receive your reward from our business associate Smeed at Scrabblescrew's Camp."] = {
		[1] = 5943,
	},
	["The Thirsty Goblin:49:Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan.:I've got an idea, see. I've heard of some strange creatures called dew collectors that live to the southwest... and that they are able to store water in special glands.\n\nI think that if I could get one of these glands, I could create a drink that would quench my terrible thirst! Do you think you could help me, Ewwor?\n\nLook for the cactus garden, Ewwor; that's where you'll find the dew collectors."] = {
		[1] = 2605,
	},
	["Singing Blue Shards:35:Bring 10 Singing Crystal Shards to Crank Fizzlebub.:The Singing Crystals are unique to Stranglethorn, and are very valuable to certain parties.  I can move those crystals, but the cursed Venture Company makes it hard for an honest entrepreneur like myself to gather any!\n\nI'd like to hire you.\n\nThe basilisks in Stranglethorn eat the crystal.  This gives them their hardened skin, and sometimes decent quality crystal can be harvested from it.\n\nYou can get it from any basilisk, but the less nasty ones are along the shores south of Zul'Kunda, to the north."] = {
		[1] = 605,
	},
	["Yuka Screwspigot:53:Speak with Yuka Screwspigot in the Burning Steppes.:Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value!  But... we might need your help to capitalize on Ribbly's newfound worth.\n\nMy sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes.  She sent word to me, asking for some hired hands.\n\nSo, what do you say?  Want to help?  If so, then speak with my sister.  You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock."] = {
		[1] = 4324,
	},
	["Welcome to the Jungle:30:Speak with Hemet Nesingwary.:Welcome to Stranglethorn!\n\nPerhaps you're not aware of this, but that dwarf over there is the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter.  He's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, druid.\n\nBeing a veteran of many battles himself, Master Nesingwary has a soft spot for fellow heroes.\n\nGo and speak with him.  Perhaps he can give you some hunting pointers."] = {
		[1] = 583,
	},
	["Investigate the Camp:32:Find the hunters' camp and report its location to Krazek in Booty Bay.:I've gotten reports of a group of hunters that have set up camp upriver of the Venture Company mining camp on Lake Nazferiti. Now, normally I wouldn't care, but improbably, I heard that Hemet Nesingwary was one of the hunters there? He's certainly well-connected, if you catch my meaning, and you never can be too safe.\n\nWhy don't you go check out the camp, Ewwor, see what they're about?"] = {
		[1] = 201,
	},
	["The Stone Circle:51:Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.:I once entered the foreboding chambers of the Sunken Temple. The evil in that place penetrates all that enter; I barely managed to find my way out, wading through the ooze that now covers the floors. All I can remember is stumbling through a large circular room, filled with serpent statues...\n\nRecently, I discovered a round stone that appeared to have the same serpent symbol imprinted on it. I had it packed up and shipped to my workshop in Ratchet. Retrieve it, and I might be able to tell you more."] = {
		[1] = 3444,
	},
	["Up to Snuff:41:Deeg in Booty Bay wants you to bring him 15 shares of Snuff.:Ah, the sea life.  I ain't gonna say it's the good life, but it's my life.\n\nWhen I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right?\n\nSo you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders.\n\nI bet a fearless druid like you could convince 'em to share the goods, eh?"] = {
		[1] = 587,
	},
	["The Second Rebellion:33:Kill 15 Kurzen Jungle Fighters.\n\nReturn to Sergeant Yohwa at the Rebel Camp.:We're fighting a losing battle with Colonel Kurzen.  Not only is he a brilliant tactician, he outnumbers us at least 10 to 1!  To survive, we need to use his own, covert tactics against him.\n\nEnter his camp to the east and kill his men.  Lots of them.  And get out before reinforcements can close on you."] = {
		[1] = 203,
	},
	["Tiger Mastery:37:Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw.:Here is the final challenge that I will put forth.  We've been tracking an elusive tiger for weeks.  We call the beast Sin'Dall.  See if you can do what no night elf has done before: hunt down and kill Sin'Dall.  Bring me her paw as proof of your accomplishment.\n\nTracking her down will be no easy task."] = {
		[1] = 188,
	},
	["Stoley's Shipment:45:Bring Stoley's Shipment to Stoley in Steamwheedle Port.:I owe \"Sea Wolf\" MacKinley in Booty Bay some rum, to settle a bet, but I'm all out of rum!  Captain Cuergo stole my last shipment, and he has it stowed in that walled pirate town to the south.\n\nIf you can find my shipment of rum and return it to me, then I can prove to MacKinley that Kalimdor's booze beats the dirt out of Booty Bay!"] = {
		[1] = 2873,
	},
	["Nekrum's Medallion:47:Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.:I'll find out where your gryphon is, but first you have to do something for me.  There's a troll in Zul'Farrak, Nekrum Gutchewer, who possesses a medallion I would very much like to study.  Bring me that Medallion and I'll use my powers to find Sharpbeak.\n\nZul'Farrak is across the ocean to the west, in the desert of Tanaris."] = {
		[1] = 2991,
	},
	["Witherbark Cages:45:Check the cages at the two Witherbark villages, then return to Gryphon  Master Talonaxe.:The son of our mightiest gryphon is gone! Swiftwing's heir, Sharpbeak, was lost while hunting with his parents a few days ago, and we believe it was the trolls who took him.\n\nYou must aid us!  Search the cages in the two Witherbark troll villages to see if Sharpbeak is there."] = {
		[1] = 2988,
	},
	["Saving Sharpbeak:51:Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.:We must save Sharpbeak!\n\nFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!"] = {
		[1] = 2994,
	},
	["Clamlette Surprise:45:Dirge Quikcleave wants you to get the following items:\n\n12 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.\n\n10 pieces of Zesty Clam Meat. You can find those in clams, naturally!\n\n20 pieces of Alterac Swiss. Get thee to a cheesery!\n\nGather all of the items and return to Dirge.:Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, Ewwor, just thinking about a clamlette makes my mouth water.\n\nUnfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal??\n\nHere's what I need:"] = {
		[1] = 6610,
	},
	["Bloodpetal Poison:52:Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater.:I would ask you to help me create a toxin of sorts, to pacify a great creature living here in the crater.  It is not deadly, and only the keen eyes of a druid can hope to collect the ingredients.\n\nYou can find the bloodcap mushrooms growing within the bloodpetal sprouts all across the crater.  Gorishi stings are from the insects inside and around the Slithering Scar, located in the southern part of the crater."] = {
		[1] = 9052,
	},
	["Lieutenant Paval Reethe:40:Find out more about Reethe from Adjutant Tesoran in Theramore.:I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books."] = {
		[1] = 1259,
	},
	["Toxic Test:52:Stab a Devilsaur with the Devilsaur Barb. Return to Torwa Pathfinder in Un'Goro Crater when you have completed this task.:The toxin you helped me create is for a special purpose.  The great devilsaurs of the crater make it dangerous to hunt and difficult for me to survive.  Even if I possessed the necessary strength, killing a devilsaur simply allows another to move into its territory.\n\nTake this poisoned barb and stab it deep into a living devilsaur.  The toxin should pacify the creature, though I do not know how quickly..."] = {
		[1] = 9051,
	},
	["Against Lord Shalzaru:45:Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.:Ewwor, new scouting reports have given us a good idea on the naga chain of command.  Royalty is present amongst their rank and file, and they're the ones calling all the shots.\n\nSpecifically, we've identified one of the crueler royals as Lord Shalzaru.  Scouts report that he himself has uncovered an odd relic during a recent naga excavation in a cave south of the main ruins, across the water on the Isle of Dread.\n\nPut a stop to it by putting a stop to him, and bring me his relic so we can study it."] = {
		[1] = 2870,
	},
	["Passage to Booty Bay:30:Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.:Ah yes, finally found it. Should have told me she passed through here that long ago. Let's see.\n\nVelinde. Booked passage to Booty Bay on the Black Osprey. I don't have anything here saying otherwise, so I'd assume it arrived in port safely.\n\nNot much more help I can be to you, but she asked about overland travel over on that side of the world, and I mentioned Ruzzgot, a caravan driver based out of Booty Bay. Might be that this Velinde traveled with him.\n\nMove along, now. I haven't all day for you."] = {
		[1] = 1040,
	},
	["Return to the Hinterlands:47:Speak with Gryphon Master Talonaxe.:Sharpbeak is held in a cage, high on a cliff at the top of Jintha'Alor in the Hinterlands.  The key to this cage is possessed by the high priestess of the Vilebranch trolls, Vile Priestess Hexx.\n\nThere.  I have done my part.  I bid you fortune on your quest, Ewwor."] = {
		[1] = 2993,
	},
	["The Captain's Chest:47:Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.:I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude."] = {
		[1] = 614,
		[2] = 8551,
	},
	["The Deserters:38:Speak with Captain Garran Vimes in Theramore about Reethe.:Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?"] = {
		[1] = 1287,
	},
	["Magical Analysis:37:Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran.:From what I've heard, the mages of Dalaran are busy with the reconstruction of their destroyed city, I'm sure you can find one of them who will spare some time to look at the bracers. If there's anything I know about mages, they can't resist a magical puzzle.\n\nTake the bag of water elemental bracers and see if they can shed any light on the Stone's curse.  Look for the Archmage Ansirem Runeweaver in particular.  I've dealt with him before, and his knowledge is vast."] = {
		[1] = 602,
	},
	["Southsea Shakedown:45:Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers.:Argh! They want the impossible from me!\n\nThe Steamwheedle Cartel wants me to teach the Southsea pirates a lesson.  The problem is that I can't be in two places at once; I need to stay here to keep the peace.\n\nOf late, the pirates have been disregarding the protection money that the cartel regularly forks over. So I'd like to temporarily deputize you to go down there and show them what for.\n\nYou'll find them at Lost Rigger Cove, which is not too far to the south.  Thanks Ewwor, I'll owe you one!"] = {
		[1] = 8366,
	},
	["Stoley's Debt:45:Speak with Stoley in Steamwheedle Port.:My old buddy Stoley owes me a very special bottle of rum.  He tends the bar at Steamwheedle Port in Tanaris, Kalimdor,  and he promised me that the rum there is stronger than anything we can find in Booty Bay.  He's so confident that he says if I try that rum and don't agree with him, then he'll double the money he owes me!\n\nWell, I think he's not as confident as he was when last we spoke, and now he's afraid to give me that rum.  But I don't back down from wagers, so why don't you talk to him for me..."] = {
		[1] = 2872,
	},
	["Supplies to Private Thorsen:32:Deliver the Miscellaneous Goblin Supplies to Private Thorsen.:Hmm. Yes, I do have something you could do, actually. Lieutenant Doren and his followers up in the north need their regular supplies from us.\n\nThey haven't been delivered, and with the trolls attacking, I'll need someone to do it. Doren's camp lies northwest of the road at the entrance to Stranglethorn from Duskwood. Give the supplies to Private Thorsen, if he's not in the camp, then he'll be patrolling south of it. He'll take care of them.\n\nMind you, if you fail, you'll owe me restitution."] = {
		[1] = 198,
	},
	["The Curse of the Tides:40:Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.:So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for. Maybe you should try there.\n\nYou got my knife back for me, so I guess you can borrow it... but I want it back when you're done!"] = {
		[1] = 611,
	},
	["The Way of the Weaponsmith:40:To become a Weaponsmith, you must make the following items and return them to Ironus: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces.\n:As a weaponsmith you'll find that more often than not, heroes and adventurers will be coming to you for gear. While the workload can be unbearable at times, the riches more than make up for the back strain and ash lung.\n\nOh yes, Unknown, weaponsmiths are the ones with all the gold!\n\nIf you wish to join our ranks, you'll need to show me that you can make me a silver or two - I mean, show me that you've got what it takes to be the go to guy when people need superior quality weapons. Get to work!"] = {
		[1] = 5284,
	},
	["Raptor Mastery:34:Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors.:So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill 10 Stranglethorn Raptors.  We'll see just how much of a big game hunter you are.\n\nAnd no, I won't tell you where you can find them!  Locating the beasts is half the challenge."] = {
		[1] = 194,
	},
	["The Knife Revealed:44:Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.:The Stronghold's resident druid, Quintis Jonespyre, has some... unusual skills.  One of them involves psychometry - the ability to reveal an item's history by touch.  Don't ask me how he does it; I chalk it up to magic I do not and choose not to understand.  I do know, however, two things: one, I've seen it work and two, the bum owes me.\n\nTake the knife up to Quint in his little tree-house here, and tell him for me that his Kalimdor Hold 'Em debt will be paid if he works his mojo on that knife."] = {
		[1] = 4129,
	},
	["Insect Part Analysis:48:Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan.  Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested.:Senior Surveyor Fizzledowser needs to see this report immediately.  Actually... everyone who can read needs to see this report.  We are facing a grave and serious threat to not only Tanaris and Gadgetzan, but if left unchecked, the entirety of southern Kalimdor.  Heck, even quite possible the whole of Azeroth; this thing has given no indication it will subside.\n\nHave Fizzledowser make a duplicate of the report for you to distribute freely to your allegiance. Everyone must know about this threat!"] = {
		[1] = 113,
	},
	["Stranglethorn Fever:45:Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage.  Bring the Heart of Mokk to Fin Fizracket.:Sick...so...very s-s-sick....\n\n...have contracted Stranglethorn Fever...deadly v-v-virus...\n\n...only cure...is...is...to eat the heart of M-m-m-m-mokk the Savage...elusive white beast...\n\n...Witch doctor Unbagwa...only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape...\n\n...hurry...dying...dying...."] = {
		[1] = 348,
	},
	["The Writhing Deep:46:Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep.  According to the note, it is located to the south of the Woodpaw gnoll camps.:Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader.\n\nThe note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, \"Raschal of Feathermoon\".\n\nIt would seem that you have located where Raschal ultimately went."] = {
		[1] = 4135,
	},
	["Facing Negolash:50:Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\n\nKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.:Negolash is a hungry giant.\n\nWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!\n\nIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!"] = {
		[1] = 618,
		[2] = 8554,
	},
	["Return to Corporal Kaleb:37:Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.:While you were gone I fixed the pot you brought me.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied."] = {
		[1] = 622,
	},
	["The Fare of Lar'korwi:53:Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.:Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nReturn to me afterwards."] = {
		[1] = 4290,
	},
	["Mai'Zoth:46:Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.:Kurzen may be dead, but...that which drove him to evil still lives!  Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn.  He is rumored to employ mind-controlling magic, and I am positive that he corrupted Kurzen.\n\nIf Mai'Zoth is allowed to live, then his evil may influence others, and may even cause another Kurzen to surface.\n\nKill him, and bring me his Mind's Eye, the artifact he uses to corrupt others."] = {
		[1] = 206,
	},
	["Fuel for the Zapping:48:Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.:If I bet against my own better judgment and stay to run an engineering shop along the Forgotten Coast, I will need to deal with these pesky elementals.  Curse the powers of elementalism unchecked, I say!\n\nFortunately for me, and now for you my hopeful agent provocateur, the elementals represent an ideal source of raw power for my Ultra-Shrinker refinement - give them the what-for I say!  When doing this though, be sure to save me the water elemental cores!"] = {
		[1] = 7721,
	},
	["Insect Part Analysis:48:Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts.:I'm going to spend some time taking a look at Scrimshank's surveying gear... as well as putting his personal effects in order.  I get the sneaking feeling behind my ears that this isn't the last loss we'll be facing against these bugs.\n\nI'd like for you to check in with Alchemist Pestlezugg to see if he has had a chance to process the insect parts we sent him.  If they're ready, bring them to me."] = {
		[1] = 110,
	},
	["Tiger Mastery:31:Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers.:When I was but a young girl, my father trained me in the art of tiger hunting.\n\nYou'll find the young felines much easier to track and slay.  For this reason, we'll start you out easy.  One can often find young tigers near the expedition camp.\n\nTest your tracking skills and see if you can hunt some of the beasts down."] = {
		[1] = 185,
	},
	["Return to Feathermoon Stronghold:43:Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.:With the discovery of the strange gazebo in the heart of the Ruins of Solarsal, the time has come to return to Feathermoon Stronghold and report to General Shandris Feathermoon what has been discovered here."] = {
		[1] = 2867,
	},
	["Freed from the Hive:46:Free Raschal from the Zukk'ash hive.\n\nReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well.:The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life.\n\n\"Thank Elune - you've saved me, friend!  I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me.  Were you sent by the Stronghold?\"\n\nIt would seem that you've found the missing courier!"] = {
		[1] = "Freed from the Hive",
	},
	["The Battle of Darrowshire:60:Place the Relic Bundle at the Darrowshire town square.\n\nPrevent Davil Lightfire's death until the death of Horgus.\n\nPrevent Captain Redpath's death until Redpath the Corrupted appears.\n\nDefeat Redpath the Corrupted.\n\nSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.:Now, Daidinn, you will take part in battle of Darrowshire, and you will save Joseph Redpath.\n\nPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\n\nAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela."] = {
		[1] = 5721,
	},
	["Testing Your Mettle:60:Bring Grimando the items he's requested.:Well well, it seems you're eager to prove your worth as a craftsman. Good, good, I love ambition. Let's see what you're made of. I need you to craft specific items using only the finest and rarest materials. This task will push you to be resourceful as well as skilled and dedicated. Don't disappoint me, I have high standards."] = {
		[1] = 10075,
	},
	["Rescue OOX-17/TN!:48:Escort OOX-17/TN to Steamwheedle Port, then report to Oglethorpe Obnoticus in Booty Bay.:The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  I need you to escort the robot from its current location to, let's say, Steamwheedle Port!  That should be a perfect place, and long enough, to get things on line!\"\n\n\"Escort it safely to the port, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\""] = {
		[1] = 648,
	},
	["Into the Depths:51:Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.:Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.\n\nI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple."] = {
		[1] = 3446,
	},
	["The Molten Core:60:Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.:Daidinn, perhaps it is time to give you a real test.  Are you ready?\n\nAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.\n\nGo to the Molten Core, Daidinn.  Show me you have the strength and the will to defeat what you find there.\n\nAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live."] = {
		[1] = 6822,
	},
	["Ship Schedules:45:Report the Ship Schedules to an authority in Steamwheedle Port.:This scroll contains the schedules of shipments between Steamwheedle Port and Booty Bay. Both past and future shipments are included, along with ship names, with large 'X's next to some ships' journeys, and annotations like \"GREAT LOOT\" and \"HARD FIGHT\" next to others.\n\nSomeone at Steamwheedle Port would want to see this document."] = {
		[1] = 2876,
	},
	["The Demon Forge:60:Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\n\nYou must also find the Unforged Rune Covered Breastplate.\n\nReturn both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.:Lorax makes deals, he does not accept them from insignificant mortals.\n\nA deal I shall make with you, however... take this pike, it is imbued with powerful Fel energies. When you find Goraluk Anvilcrack, slay him and drive this pike through his dying heart. His soul he bartered, his soul I shall have. Return the pike and return the breastplate that the thief stole and I shall teach you what it is that he was to learn."] = {
		[1] = 5127,
	},
	["Tooga's Quest:50:Show Tooga the way back to his wife, Torta.:I am so lost!\n\nMy wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere.\n\nWould you be so kind as to lead me back to Torta? She's waiting for me just south of Steamwheedle Port."] = {
		[1] = 1560,
	},
	["Hostile Takeover:36:Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.:He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!\n\nRevilgaz won't have it, and he's told me to take care of the problem in my own way.\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti are deeply interested in those strange blue crystals they have been finding in the mines. Bring me samples of the stone from their geologists, I don't care what you have to do to get them."] = {
		[1] = 213,
	},
	["The Eastern Pylon:53:Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.:During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, Ewwor. I guess that they are quite large, with crystals lining their interiors.\n\nAlthough I've never seen one, I can't help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found\n\nSo why don't you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?"] = {
		[1] = 4287,
	},
	["Stone Extraction:1:Gather 100 stone samples by mining.:Mining encompasses more than just the pursuit of precious ores; understanding stone extraction is essential. I want you to mine and gather 100 stone samples. Pay attention to the different types of stone and their properties. This will be a valuable lesson in the diversity of materials you will encounter."] = {
		[1] = "Stone Extraction",
	},
	["The Dunemaul Compound:49:Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.:Just recently, a large bank of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound. Several smaller bands are currently wandering the desert, some of which have invaded the old troll ruins.\n\nThe Dunemaul Compound must be destroyed! We cannot allow these ogres to build up a force.\n\nThe leader of this band is named Gor'marok the Ravager; I believe that putting an end to his leadership will be the beginning of the end for the ogres."] = {
		[1] = 5863,
	},
	["Gadgetzan Water Survey:46:Use the untapped dowsing widget near the pool of water by Sandsorrow Watch.  Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan.:We've got a position open for a temporary junior-grade surveyor in the Gadgetzan Water Company, if you're interested!\n\nWith the nomads seizing all our wells, we need to exploit more free sources of water!  There is water to be had in the desert, but only to those smart enough to survey them first.\n\nTake this dowsing widget and tap a sample of the water by the pool near Sandsorrow Watch.  It's right in sight of the trolls around there.  Bring the tapped widget back to me when you're done!"] = {
		[1] = 992,
	},
	["Wastewander Justice:43:Take down 10 Wastewander Bandits and Thieves east of Gadgetzan, then report back to Chief Engineer Bilgewhizzle.:You there!  It's time for you to be a big helper to the Gadgetzan Water Company.\n\nThe Wastewander nomads out in the Tanaris desert have seized almost all the water wells!  Without access to them, our water supply will dry up in no time.  If you want to get in our good graces, then you'll help us bring justice to those nomads!\n\nHead east of here and bring down ten Wastewander Bandits and Thieves, then report back to me on the double.  Justice waits for no man... goblin... bah, just get on it!"] = {
		[1] = 1690,
	},
	["Zapped Giants:48:Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.:I'm going to have to do something about the giants if I stay out here!  They're certainly not good for business, now are they?\n\nI've been working on a variant of a gnomish shrinking ray, but I'm using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on any of the giants in Feralas.  You should find miniaturization residue on them after you shrink them - bring me back some!"] = {
		[1] = 7003,
	},
	["The Spy Revealed!:37:Take the Muddy Note to Lieutenant Doren at the Rebel Camp.:Among the valuables of the strongbox is a muddy, scribbled note.  Although barely legible, it looks to be an itinerary for Private Thorsen.  It details his patrol routes, who he speaks with and how he spends his time with the rebels.  It's signed with only one letter: -M.\n\nBut whoever wrote this note must have stayed very close to Thorsen.  Whoever wrote this note is the traitor within the rebel camp."] = {
		[1] = 329,
	},
	["The Black Shield:35:Show the Blackened Iron Shield to Caz Twosprocket in Theramore.:I'm sorry I can't be of much help, Ewwor, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you."] = {
		[1] = 1319,
	},
	["Bungle in the Jungle:53:Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.:My research revealed to me that the silithid are like bees; destroy the queen of the hive, and the rest of should be thrown into disarray.  I'll brew a lure that we'll use to bring out the queen; once summoned, you'll take her down.\n\nFirst though, we need some reagents; we don't want you bungling into the jungle unprepared.  Go west to find the silithid hive in Un'Goro Crater and obtain a scent gland from one of the bugs.  I'll also need some samples of the native Un'Goro soil."] = {
		[1] = 4496,
	},
	["The Scrimshank Redemption:48:Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.:Oh, this is just terrible!  I sent out my top assistant, Junior Surveyor Scrimshank, into the desert southeast of here.  That's an area we call the Gaping Chasm.  Well, he's gone missing, and his last report had more of those weird bugs where he was.  Could it be that they've infested two major regions of the desert now?\n\nI need you to head into the Gaping Chasm and look for Scrimshank, please!  That... or at least find his surveying equipment.  I fear that may be all that is left of the poor sod."] = {
		[1] = 10,
	},
	["Sprinkle's Secret Ingredient:49:Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her.:When I was a kid, my sister used to do all the cooking. It was horrible! I could barely stomach some of her concoctions -- until I found what I like to call my \"secret\" ingredient! Add it to anything, and... WOW! It tastes great!\n\nWhat is it, you ask? It's a mushroom called the Violet Tragan. If you want me to help you turn this horrid-tasting brew into something edible, head to the Hinterlands, and look for a small lake there.\n\nOh, and remember, the Violet Tragan can only be found underwater."] = {
		[1] = 2641,
	},
	["I Know A Guy...:45:Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.\n:I can tell by yer cooking spoon that ye know what yer doin'. Unfortunately, I can't teach ya nothin'.\n\nLuckily fer ye, I know a guy. He's a goblin and probably the best cook on Kalimdor.\n\nAyep, that's the bad news, $g lad:missy; - ye got to travel to Kalimdor. Git to Gadgetzan and find Dirge Quikcleave. He'll set ya straight.\n"] = {
		[1] = 6612,
	},
	["Troll Temper:45:Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.:The Sandfury trolls of Zul'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft, yes I can!  It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I'll reward you well.\n\nZul'Farrak is northwest of Gadgetzan.  Good luck."] = {
		[1] = 3042,
	},
	["Refuel for the Zapping:55:Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.:More work, you say?  Did my heroic mission of collecting bits of goo found inside elemental beings not slake your thirst for adventure?  Perhaps more of the same will vainly try to fill the bottomless well of questing you possess...\n\nOK, melodrama aside, I do need more water elemental cores.  I'm trying desperately to set up shop here, so the rewards won't be as great... but I promise you I'll tell everyone in earshot how you've helped me.  Trust me on this - I know people in the Cartel!"] = {
		[1] = 7726,
	},
	["In Good Taste:49:Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan.:Blech! This stuff tastes terrible! So much for that idea...\n\nWait, what's that? Oh, I know, I know, you think I shouldn't give up on this stuff. Well, okay then.\n\nUhhhh, I have an idea! Brilliant! Take this dew to my friend Sprinkle -- she's an excellent chef. Tell her what we're up to here and that we want to make it go down a little easier.\n\nI mean, if it's going to taste that bad, it at least should have some kick to it... And I'm just not feeling it... "] = {
		[1] = 2606,
	},
	["Thistleshrub Valley:50:Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.:Have you ever seen Thistleshrub Valley? It's a mighty dangerous place, Ewwor.\n\nThose strange beasts there, I don't trust them for a minute! Gnarled thistleshrubs and thistleshrub rootshapers, that's what I think they were called...\n\nAnyhow, I want to get into the valley, but with so many of those thistleshrubs around, there's no way I'm going back there. But here's where you come in -- if you clear some of them out, I just might think about going back. What do you think, Ewwor? Help me out?"] = {
		[1] = 3362,
	},
	["The Apes of Un'Goro:55:Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.:This crater has many strange creatures--they seem to be nobler versions of the creatures found throughout my homeland and beyond. I cannot explain it, but this place cries of the Earth Mother. I pay homage to her every time I track one of her beautiful creatures across its basin.\n\nIf you too wish to feel the enlightenment that accompanies such a great feat, then head to the north. There you'll find great apes who are a test for any mortal's strength. Bring me their pelts... prove your strength."] = {
		[1] = 4289,
	},
	["Scaring Shaky:41:Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay.:If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me. Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt Elder Mistvale Gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst."] = {
		[1] = 606,
	},
	["The Missing Courier:43:Speak with Ginro Hearthkindle in Feathermoon Stronghold.:An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying.  It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse.  Unfortunately, I have had to declare the courier as missing in action.\n\nIf you have the time and resources to spare, please speak with Ginro.  He should be here in the Stronghold - perhaps in his quarters."] = {
		[1] = 4124,
	},
	["The Bloodsail Buccaneers:41:Report the planned Bloodsail attack to Fleet Master Seahorn.:Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders!\n\nThis is bigger than I thought.  Report what you have learned to Fleet Master Seahorn at once!  The ol' sea dog is around town somewhere...."] = {
		[1] = 599,
	},
	["The Darkmoon Faire:60:Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival.:The Darkmoon Faire is coming!  Be sure to experience all the wonders and excitement of it when it comes to town!\n\nIf you act right now, you can redeem this voucher for free prize tickets!  Just hand your voucher to Gelvas Grimgate located inside the carnival.\n\nRight now, the Faire is outside Goldshire, in the Elwynn Forest.  Don't miss out!  Go today!"] = {
		[1] = 7905,
	},
	["Jungle Secrets:33:Speak with Lieutenant Doren at the Rebel Camp.:Thank you for saving me, Ewwor.  I know how this looks, but...allow me to explain.\n\nI was charged by Lieutenant Doren to re-enlist with Kurzen's men, so that I might spy on them and bring sorely needed intelligence to the rebels.  You saw here what I had thought would be my chance to infiltrate Kurzen's Compound.  I was wrong, and again, thanks for saving me.\n\nThis was a top secret mission, so you must tell no one.  But if you speak with Doren he will explain."] = {
		[1] = 215,
	},
	["Thadius Grimshade:47:Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands.:Take this feather to Thadius Grimshade, the diviner.  He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!\n\nAnd perhaps his talents can help us find Sharpbeak.\n\nThis feather was taken from the nest where the gryphon child sleeps.  If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.\n\nGood luck, Ewwor.  You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep."] = {
		[1] = 2990,
	},
	["Ore Yield:1:Gather 100 ore samples by mining.:In mining, efficiency and quantity go hand in hand. Your next challenge is to mine and gather 100 ore samples. This will test not only your endurance but also your ability to identify and efficiently extract valuable ores from the earth. Remember, quantity should not come at the expense of quality."] = {
		[1] = "Ore Yield",
	},
	["Gahz'ridian:48:Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments.:Ewwor, I'm a scientist, but also a treasure hunter at heart!\n\nLong ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity. These ornaments are carved out of an element that I call \"Gahz'ridian,\" after the hydra god.\n\nI did find some myself, but I'd like to have some more to study -- maybe you can find some?\n\nI even invented a detector that makes finding the Gahz'ridian a snap! Just put it on, and the search begins! "] = {
		[1] = 3161,
	},
	["Rescue OOX-22/FE!:45:Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.:The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the dock along the Forgotten Coast!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely to the dock, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\""] = {
		[1] = 2767,
	},
	["The Black Shield:35:Speak with Captain Garran Vimes in Theramore.:Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help."] = {
		[1] = 1320,
	},
	["Cuergo's Gold:45:Find Cuergo's gold!:This map shows a stretch of beach with a southern face.  Below the map are words, elegantly written...\n\n\nSouth of Wheedle\nSouth of home\nFind a mast and flag and bones\nDig you there, if you be bold\nDig and claim Cuergo's gold!\nA key you'll need and a key you'll see\nThe men you face take blood as fee."] = {
		[1] = 2882,
	},
	["The Bloodsail Buccaneers:41:First Mate Crazz wants you to check the cove north of Booty Bay.:You sure seem eager to work, matey.  Not sure why some land-loving night elf druid is offering help to the Blackwater Raiders, but I'm not going to turn you away.\n\nOur ship just docked here in Booty Bay and word has it that our rivals--those damned, dirty Bloodsail Buccaneers--have been spotted all over southern Stranglethorn.\n\nAll the boys are too busy hitting the grog and looking for ladies!  What I need is a scout.\n\nCheck the cove just north of Booty Bay along the Savage Coast and see what you find."] = {
		[1] = 595,
	},
	["Water Elementals:37:Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.:The water elementals were no doubt summoned by Gazban, the goblin wizard rumored to have discovered the Stone of the Tides. As you may know, the Stone of the Tides curses its bearer, causing him to fade in and out of existence...\n\nPerhaps we can find a way to counteract the curse. We can have a mage of Dalaran analyze the magical residue of one of the water elemental's bracers. I need you to go back to the island and retrieve a few specimens."] = {
		[1] = 601,
	},
	["A Better Ingredient:52:Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder.:It is as I feared -- the toxin is simply too weak for such a powerful creature.\n\nIf we are to create a toxin of high enough potency, you must venture to the bottom of the Temple of Atal'Hakkar, unlock the secrets of the altar and recover a putrid vine from the guardian there.  The temple is dangerous, and it would behoove you to bring friends.\n\nReturn to me when this is done."] = {
		[1] = 9053,
	},
	["WANTED: Andre Firebeard:45:Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port.:The vile pirate Andre Firebeard is wanted for crimes against Steamwheedle and Gadgetzan.\n\nBy decree of governing counsel, any who read this are hereby authorized to use lethal force during the apprehension of Andre and his abettors.\n\nBy further decree, should Andre be deceased, or otherwise indisposed, during the time of his hearing, his head may act as proxy, and deliverance of such head to Security Chief Bilgewhizzle constitutes a binding, and tenderable, contract."] = {
		[1] = 2875,
	},
	["Skulk Rock Clean-up:48:Kill 10 Green Sludges and 10 Jade Oozes, and then report back to Fraggar Thundermantle in Aerie Peak.:We Wildhammers remember the past, more than our brothers in Ironforge.  If you want to make friends here, then you get your hands dirty for us!\n\nThe Horde abandoned their positions in the Hinterlands around Skulk Rock; it's now overrun with nasty sludges and oozes.  We've got plans on that area, but first we need a clean-up crew to make a hole for us.\n\nThat's where you come in, Sunshine!  Head down there and take out ten green sludges and ten jade oozes, then report back to me here.  Move out!"] = {
		[1] = 2877,
	},
	["The Molten Core:60:Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.:$n, perhaps it is time to give you a real test.  Are you ready?\n\nAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.\n\nGo to the Molten Core, $N.  Show me you have the strength and the will to defeat what you find there.\n\nAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live."] = {
		[1] = 6822,
	},
	["Order Must Be Restored:60:Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.\n\nKeep your wits about you, Daidinn. The Horde will defend the ranger lord with their very lives.:Do you know how many ranger lords exist in this world? How many human ranger lords have ever existed?\n\nNathanos' accomplishments were unprecedented. He was a tactical genius, responsible for Alliance victories spanning a decade of conflict.\n\nAnd now... the champion of the Forsaken.\n\nNo. This cannot be. Order must be restored.\n\nGather an army, Daidinn. Return to the Plagues with your army and destroy the Blightcaller.\n\nI wish you luck, Daidinn. Truly, you will need it for this battle."] = {
		[1] = 6187,
	},
	["Ansirem's Key:37:Talk to Catelyn in Booty Bay.:The mage that is in possession of the Stone is amplifying its power through some focal point... an altar of some sort. You should be able to disrupt it by overpowering it.\n\nAs it happens, I know just the thing: an ancient dagger, another troll relic. There's just one... little problem.\n\nYou see, I found the dagger while researching in Stranglethorn, but I gave it to my willful daughter, Catelyn, who ran off to Booty Bay to become a pirate."] = {
		[1] = 603,
	},
	["In Search of Knowledge:47:Talk to Daryn Lightwind in Rut'theran Village.:While the ruins of Feralas can be quite dangerous, they have much to tell of what has happened here.\n\nSearching through the rubble to the south a few days ago, I discovered what appears to be a normal stave. However, I just can't shake the feeling that there is something more to it. Angelas and I have been poring over our books here, but we can't find a thing about it.\n\nI have a colleague in Darnassus that may be able to tell us what this is, Ewwor. Why don't you go talk to her and see if she can help us?"] = {
		[1] = 2939,
	},
	["Special Forces:38:Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.\n\nReport to Lieutenant Doren at the Rebel Camp.:Now that many of his regular troops are reduced, you must face his highly trained forces.  When they're not in the wilderness slaughtering our rebel soldiers, they are found deep in the back of the Kurzen Compound, in a cave they call the Stockpile.\n\nI know many of Kurzen's troops personally, and I know they are skilled, loyal, and cruel.  This is no easy task I set before you, Ewwor.\n\nAfter you defeat them, report to Lieutenant Doren, my commanding officer.  He will want your report firsthand."] = {
		[1] = 574,
	},
	["The God Hakkar:53:Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.:Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.\n\nHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.\n\nDefeat him, and place his essence within the egg of Hakkar."] = {
		[1] = 3528,
	},
	["Raptor Mastery:43:Hemet Nesingwary wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.:Because you proved yourself to be such a go-getter in the jungle, let me tell you about a ferocious raptor that even I have failed to kill.  Ajeck here calls this wily raptor Tethis.\n\nIf you want to prove yourself a true master, kill Tethis and bring me his talon.  It would be a feat that no other big game hunter has accomplished."] = {
		[1] = 197,
	},
	["Voodoo Dues:44:Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay.:My list is shortening, but there are still people who owe me.\n\nNext, we have Maury \"Club Foot\" Wilkins, Jon-Jon the Crow, and Chucky \"Ten Thumbs.\"\n\nThese scurvy dogs' debts are months outstanding and I thought they skipped town to avoid paying up!  Later, I heard they're cursed and bewitched and now wander the jungle ruins.  But I don't care what their fate is - I want what's mine!\n\nThey're at the Ruins of Aboraz and the Ruins of Jubuwal, northeast of here.  Find them, and collect."] = {
		[1] = 609,
	},
	["Find OOX-17/TN!:48:Bring the distress beacon to Oglethorpe's homing robot.:You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"The name's Oglethorpe, and my homing robot has gone missing!  I will reward you for its recovery!  Please take this beacon to the robot.  Excellent, I now have computed the coordinates for you!  It crashed near the Gaping Chasm in Tanaris!\""] = {
		[1] = 351,
	},
	["Supply and Demand:31:Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.:\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in northern Stranglethorn."] = {
		[1] = 575,
	},
	["Rise of the Silithid:46:Bring Raschal's Report to Gracina Spiritmight in Darnassus.:I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all.\n\nYou're dismissed - good luck, Ewwor; may Elune watch over us all."] = {
		[1] = 4267,
	},
	["Handle With Care:47:Bring the Carefully-packed Crate to Erelas Ambersky in Rut'theran Village.:Ewwor, I can see you yearn to be dedicated to my worthwhile cause. Yes, of course, you can do something for me!\n\nTake this crate of eggs to Erelas Ambersky. He is a druid that cares for these eggs, helping them to hatch and then training the young hippogryphs. You will find him in Teldrassil, in a small village to the south called Rut'theran."] = {
		[1] = 3022,
	},
	["Torwa Pathfinder:52:Speak with Torwa Pathfinder in Un'Goro Crater.:A hunter by the name of Torwa Pathfinder has requested the help of a druid.  He said only we would possess the necessary skills and respect for nature to help him.\n\nThere is a road that connects the Un'Goro Crater and the desert of Tanaris.  As that road enters the crater, you will find Torwa close by."] = {
		[1] = 9063,
	},
	["Petty Squabbles:57:Speak with the Fallen Hero of the Horde at the border of the Blasted Lands and the swamp.:We fight the wrong enemy, Ewwor.\n\nThe true power in these lands continues to grow in strength and number while we squabble over scorched earth with orcs.\n\nDo we continue to fight a war in these lands against the Horde, only to be routed one day by the armies of the Burning Legion? It is futile.\n\nPut your differences aside, Ewwor, speak with the fallen hero of the Horde. He knows the truth behind the Blasted Lands."] = {
		[1] = 2783,
	},
	["Panther Mastery:40:Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.:You've almost proven yourself to be a master hunter of panthers.  A panther by the name of Bhag'thera has been prowling the jungle.  So far he's eluded our party.  See if you can use your skills to kill the great Bhag'thera.\n\nBring me the Fang of Bhag'thera and you'll have earned my respect!"] = {
		[1] = 193,
	},
	["Bad Medicine:34:Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.:To have a chance against Kurzen, we need his healing support neutralized.  He has gathered around him a large number of Medicine Men who heal his forces with Jungle Remedies and poison our fighters with Venom Fern Extracts.\n\nWe need those remedies to cure our own people, and we need a sample of those extracts to study so we can make our own remedies.  Search the Kurzen Compound for both - his Medicine Men will have the remedies, and the extracts are probably stowed in some of the camp's supply boxes."] = {
		[1] = 204,
	},
	["A Scholarly Gamble:60:Speak to Lorekeeper Lydros in Dire Maul and inquire about the specialized recipes they have improved upon.:Ah, just the adventurer I was hoping to see! You won't believe what's happened. Our painstakingly researched recipes for potent elixirs have been discreetly acquired by the Shen'dralar, the ancient Highborne scholars. Even more incredible is that they've allegedly refined it further.\n\nI urge you to journey to Dire Maul and consult Lorekeeper Lydros. This is a unique opportunity to access something even more potent than our original concoctions. Go on, find out what they've done with our research."] = {
		[1] = 10088,
	},
	["Further Instructions:27:Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.:The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.\n\nRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.\n\nWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him."] = {
		[1] = 1095,
	},
	["The Molten Core:60:Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.:Unknown, perhaps it is time to give you a real test.  Are you ready?\n\nAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.\n\nGo to the Molten Core, Unknown.  Show me you have the strength and the will to defeat what you find there.\n\nAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live."] = {
		[1] = 6822,
	},
	["Super Sticky:54:Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan.:I'm always looking for a quick way to earn a gold, Ewwor. If you help me with my newest idea, I'll let you in on a little of the profit. How does that sound to you?\n\nI thought so!\n\nHead to the tar pits in northern Un'Goro Crater, and collect me some tar. Not just any tar, now, you'll need to get it from the beasts that live around the tar pits. Regular tar just simply isn't sticky enough.\n\nThe plant-like creatures contain chlorophyll in their skin, and mixed with the tar, it's super sticky!"] = {
		[1] = 4504,
	},
	["Daelin's Men:38:Return the information about Reethe to Captain Garran Vimes in Theramore.:Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing."] = {
		[1] = 1285,
	},
	["Report to Doren:37:Speak with Lieutenant Doren.:Did Lieutenant Doren want you to report back to him with that patrol information?"] = {
		[1] = 331,
	},
	["Zanzil's Secret:44:Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.:Zanzil the Outcast dwells with his followers in the Jubuwai and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well...\n\nZanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies.\n\nHis mixture would be worth much to those who wish to control others.\n\nBring me samples of his mixture, and I will find a use for them."] = {
		[1] = 621,
	},
	["The Stone of the Tides:37:Find the haunted island for Baron Revilgaz in Booty Bay.:If there is indeed a goblin mage and water elementals haunting the island, it could mean the Stone of the Tides can be mine!\n\nI want you to locate this haunted island... find out what's going on. Oh, and if you perhaps want to find out more about the Stone of the Tides, take this scrip to the Stormwind Library, they should be able to find you a copy of the book I first came across the legend in.\n\nCould it be that Gazban actually discovered the Stone...?"] = {
		[1] = 578,
	},
	["Delivering the Relic:45:Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.:If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it.  She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere.  I couldn't make heads or tails of this device even if there was a wager involved.  My wife though, if anyone can figure out what this thing is, she could... and we need to know!\n\nShe's just around the bend, no doubt studying.  Thanks, Ewwor."] = {
		[1] = 2871,
	},
	["Nat Pagle, Angler Extreme:45:Nat Pagle wants you to catch the following fish:\n\nMisty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.\n\nA Sar'theris Striker from the Sar'theris Strand in Desolace.\n\nFeralas Ahi from the Verdantis River of Feralas.\n\nSavage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.\n\nReturn to Nat Pagle when you have reeled them all in!:Can't say I really enjoy fishin' much. Figure I been at it for a good 20 or 30 years now.\n\nI reckon people are driven to do what they do for different reasons.\n\nNow, I'm not saying you need to fish for 30 years or catch every fish in the sea to become a master fisherman. I reckon you just need to be determined - determined enough to sit on your duff for hours at a time, doin' nothin'.\n\nI'll tell you what, catch me a few rare fish and I'll teach you a thing or two. Here's a list:"] = {
		[1] = 6607,
	},
	["Wandering Shay:49:Pick up Shay's Bell from the chest.\n\nEscort Shay Leafrunner to Rockbiter's camp.:Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then. There are just so many things to see, and I get so distracted.\n\nThere is one thing that will always work to get my attention, though.\n\nInside this chest, you'll find a bell that is very precious to me. I just love the sound of it. You have my word, if I wander off, all you have to do is ring it and I'll come running back."] = {
		[1] = 2845,
	},
	["Screecher Spirits:44:Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.:I seek the spirits of the vale screechers of Feralas.  They are the cousins of an old, old god, and their spirits are linked to him.\n\nTake this bramble wand and go to Feralas.  Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies.  This will coax their spirit to reveal itself.  Touch the spirit and collect its essence.\n\nReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke."] = {
		[1] = 3520,
	},
	["Return to MacKinley:41:Bring Shaky's Payment to \"Sea Wolf\" MacKinley:Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!!\n\nI just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!"] = {
		[1] = 607,
	},
	["The Divination:47:Wait until Grimshade performs the ritual of divination.:Give me room while I perform a ritual of divination.  I will find the connection between the feather you brought me and its owner, and follow that connection to Sharpbeak himself.\n\nThat is... I will if all goes according to plan.  If it does not, then... you better close your eyes."] = {
		[1] = 2992,
	},
	["Against the Hatecrest:43:Report to Latronicus Moonspear in Feathermoon Stronghold.:At this point, I am going to direct you to my second, Latronicus.  He's been keeping a close eye on the naga forces to date.  I'll assess the general situation here in regards to the naga; as much as I want to commit a full force to move against them, leaving the stronghold open to direct attack from the Horde - or worse - seems less than optimal.\n\nAnyway, Latronicus awaits.  Good work thus far, Ewwor.  Keep it up.\n\nYou're dismissed."] = {
		[1] = 3130,
	},
	["Suspicious Hoofprints:35:Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.:Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh."] = {
		[1] = 1284,
	},
	["Chapter I:40:Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.:Chapter I was quite riveting!  Master Nesingwary sets the backdrop for the story and makes mention of his hunting companions, including me! \n\nBut that's besides the point.  Let me see which pages are still missing.  It seems pages 1, 4, 6 and 8 are still out there somewhere in the jungle!"] = {
		[1] = 339,
	},
	["The Captain's Cutlass:50:Speak with Sprogger.:After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant."] = {
		[1] = 8553,
	},
	["The Altar of Zul:48:Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe.:Sharpbeak was not with the Witherbark trolls.  Perhaps the Vilebranch trolls took him.  Go to the Altar of Zul on the western edge of Vilebranch territory and search for the gryphon child. "] = {
		[1] = 2989,
	},
	["WANTED: Caliph Scorpidsting:46:Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan.:WANTED: Caliph Scorpidsting!\n\nThe Gadgetzan Water Company of Gadgetzan, Tanaris will pay a high bounty for the head of Caliph Scorpidsting, leader of the Wastewander outlaws.  His crimes include:\n\n1.  Murdering Gadgetzan Water Co. employees!\n2.Stealing Gadgetzan Water Co. resources!\n3.Seizing Gadgetzan Water Co. property!\n\nBring proof of Caliph Scorpidsting's demise to Chief Engineer Bilgewhizzle for an immediate reward!"] = {
		[1] = 2781,
	},
	["Jonespyre's Request:50:Speak with Quintis Jonespyre in Feathermoon Stronghold.:Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do."] = {
		[1] = 3787,
	},
	["Against the Hatecrest:43:Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.:The best course of action at this point is to assume that, regardless of what the naga are up to, they will eventually move to secure the island for their own.  We need to take aggressive steps to counter that threat before it is too late.\n\nBring me ten Hatecrest Scales that are in good condition; it should be obvious to you how to acquire them.  You'll cut your teeth on the naga for the first time, and we'll have a weakened naga presence on Sardor Isle - both are prospects that play to our advantage."] = {
		[1] = 2869,
	},
	["The Ruins of Solarsal :43:Explore the Ruins of Solarsal and investigate the presence of the naga there.:To our south are the Ruins of Solarsal; this is an area that far pre-dates modern times.  We explored the ruins initially and found nothing of note; as such, we left it in peace.\n\nVery recently, the Hatecrest naga have occupied these ruins in alarming numbers.  At first, we considered it as the precursor for an attack.  Though that threat is still possible, we believe there might be something else going on.\n\nGo there, explore the ruins, and look for anything that stands out to you. Good luck, Ewwor."] = {
		[1] = 2866,
	},
	["The Ancient Egg:50:Bring the Ancient Egg to Yeh'kinya in Tanaris.:The Prophecy of Mosh'aru speaks of an ancient egg.  It is a relic of a time when trolls ruled vast empires, and it has the power to hold the essence of Hakkar.  It may be the only way to keep our world safe from his evil.\n\nBring me the ancient egg, Ewwor.  It is said to lay hidden deep within Jintha'Alor in the Hinterlands, in a cave behind the amphitheater at the top of the city."] = {
		[1] = 4787,
	},
	["Reception from Tyrande:28:Find Tyrande Whisperwind in Darnassus.:Ewwor, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.\n\nIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.\n\nIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus."] = {
		[1] = 1081,
	},
	["Scarab Shells:45:Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.:The scarabs of Tanaris have very hard shells!  Hard enough to use as a building material for lots of things.  So many things!\n\nIn fact, those shells are so useful... the scarabs were hunted all to near extinction!\n\nI know where there are more scarabs, and if you promise to bring me their shells then I'll tell you where they are.  Promise?\n\nOk, the scarabs have a colony in Zul'Farrak.  I guess the trolls don't hunt them for their shells.\n\nBut you can!  Go to Zul'Farrak and get me uncracked shells!"] = {
		[1] = 2865,
	},
	["The Way of the Weaponsmith:40:To become a Weaponsmith, you must make the following items and return them to Ironus: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces.\n:As a weaponsmith you'll find that more often than not, heroes and adventurers will be coming to you for gear. While the workload can be unbearable at times, the riches more than make up for the back strain and ash lung.\n\nOh yes, Ewwor, weaponsmiths are the ones with all the gold!\n\nIf you wish to join our ranks, you'll need to show me that you can make me a silver or two - I mean, show me that you've got what it takes to be the go to guy when people need superior quality weapons. Get to work!"] = {
		[1] = 5284,
	},
	["Big Game Hunter:43:Hemet Nesingwary wants you to bring him the head of King Bangalash, the great white tiger.:Ewwor, you are a hunter worthy of our company.  From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated.\n\nYou have killed the ferocious Sin'Dall, the elusive Bag'thera and the treacherous Tethis.  But the true prize is the head of King Bangalash.  That white tiger is the reason I am here.  I've had my sights on him for quite some time now.  Kill King Bangalash and your hunting prowess is proven to be second to none."] = {
		[1] = 208,
	},
	["Psychometric Reading:44:Speak with Ginro Hearthkindle in Feathermoon Stronghold.:I'm a little wobbly still, sorry.  Anyway, I received some useful visions.\n\nRaschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however.  I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called.  He's very worried - almost terrified - about something.  So much so, that he is not paying attention to water elementals forming behind him.  The images... stop there.\n\nI need to rest, sorry Ewwor.  Tell Gin what I've seen.  He needs to know."] = {
		[1] = 4130,
	},
	["Colonel Kurzen:40:Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.:You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself.  You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!\n\nHe commands his men from deep within the Stockpile.  You must enter that cave, brave through his defenders, and face Kurzen and his leaders.\n\nFarewell, Ewwor.  My hope, and the fate of my men, go with you."] = {
		[1] = 202,
	},
	["Troll Witchery:40:Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.:While I study those legends you acquired, gather for me implements of evil troll magic.  Enter the territory of the Skullsplitter trolls, a second tribe to the distant south, and acquire Skullsplitter Fetishes from their Witchdoctors and Mystics."] = {
		[1] = 205,
	},
	["The Scent of Lar'korwi:53:Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.:I'm actually surprised he has not come for you yet, Ewwor. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands."] = {
		[1] = 4291,
	},
	["The Mighty U'cha:55:Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.:While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north. You have been to that cave before, but this time, I wonder if you'll survive the encounter if you accept my task.\n\nI call him U'cha, and he is one of the Earth Mother's greatest sons, of that you can be sure. Defeat U'cha and bring me his pelt. Do this, and I will defend your right to call yourself a great hunter."] = {
		[1] = 4301,
	},
	["Fire and Brimstone:60:Defeat Ragnaros, the Firelord.:Ragnaros has been reawakened by Sorcerer-Thane Thaurissan and now threatens to reduce Azeroth to ashes. Prepare yourself, $N, for your first trial is by fire. Head down to the very depths of Molten Core and defeat Ragnaros, the Firelord. \n\nTo say that this isn’t an easy task would be a major understatement. You must be prepared! Gather any help you can muster, either from the ranks of the Companions or anyone else who is foolish enough to join you on this perilous endeavor. Molten Core is one of the hottest places in Blackrock Mountain so make sure to bring plenty of fire resistance equipment and aqual dousers. \n\nShould you succeed, you will not only have saved our world, but this will also elevate you in our ranks. Make haste, $N, for the scorched earth is spreading by the day and soon enough there won't be anything left to save.\n"] = {
		[1] = 10034,
	},
	["The Basics V:16:Purchase the Barber's services.\n\nSpeak with the companion representative at the Innkeeper in the city to receive your reward.:Everyone knows that if you don't look good you deal negative damage.\n\nThe companions like to get a haircut as well.\n\nYou can visit the Barber and fully customize your appearance both for yourself and your companions.\n\nYou can even save and load customization presets.\n\nVisit the Barber and purchase his services.\n\nShearlock Combs can be found in Stormwind in the guild registration building.\n\nEdward Stylehands can be found Orgrimmar in the guild registration building."] = {
		[1] = "The Basics V",
	},
	["Counter Strategy:60:Defeat General Drakkisath.:Bad news, Daidinn! We have received reports that Nefarian’s General of the dragonspawn armies, Drakkisath, is winning the fight against the Dark Iron dwarves and might soon be setting his sights outside of Blackrock. In order to ensure that this cunning strategist isn’t going to have the upper hand against us, we want you to put together a select group of elite adventurers and strike preemptively.\n\nThis mission will require more coordination than before as you will be in command of a larger group. We believe that all your past achievements have forged you into a formidable fighter and that you are capable of seeing this through. \n\nShould you be successful, we can use Drakkisath’s resources to bolster our own capabilities. You will stand to benefit too, of course. Take whatever gear you can find in the Upper Blackrock Spire and become stronger together with the Companions!\n"] = {
		[1] = 10030,
	},
	["Chapter III:40:Bring pages 18, 20, 21and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.:Chapter III was my favorite.  It tells of Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle.  And the end of Chapter III, why, such a cliffhanger!  \n\nLooks to me as though we still need pages 18, 20, 21 and 24 to finish the chapter.  Those pages are out there somewhere. . ."] = {
		[1] = 341,
	},
	["The Bloodsail Buccaneers:43:Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.:Crazz speaks highly of your dedication to the Blackwater Raiders.  I am going to trust you with a mission of extreme importance to the fleet.\n\nInfiltrate the so-called southern command post the Bloodsail Buccaneers have established on the Wild Shore.  Raid the encampment.  Bring me their charts along with their written orders.  We shall see exactly what those scum are up to."] = {
		[1] = 604,
	},
	["Further Instructions:21:Deliver the Sealed Envelope to Sputtervalve in the Barrens.:This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.\n\nSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow."] = {
		[1] = 1094,
	},
	["I Know A Guy...:45:Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.\n:I can tell by yer cooking spoon that ye know what yer doin'. Unfortunately, I can't teach ya nothin'.\n\nLuckily fer ye, I know a guy. He's a goblin and probably the best cook on Kalimdor.\n\nAyep, that's the bad news, lad - ye got to travel to Kalimdor. Git to Gadgetzan and find Dirge Quikcleave. He'll set ya straight.\n"] = {
		[1] = 6612,
	},
	["Boat Wreckage:44:Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.:Running your hand along the mud, your fingers graze the handle of a knife.  It looks well cared for, and it might be safe to assume that whoever was on the boat might have lost it.  Perhaps the large chunk of the missing boat might have something to do with the loss.\n\nYou grab the knife, remembering that Ginro Hearthkindle in the Feathermoon Stronghold instructed you to return to him with any found clues.  You get the feeling, however, that you are not quite alone in the water..."] = {
		[1] = 4127,
	},
	["Pawn Captures Queen:54:Defeat the Gorishi Hive Queen once she is summoned.\n\nBring the Gorishi Queen's Brain to Alchemist Pestlezugg in Gadgetzan.:Here's the lure.  Inside the hive network should be a crystal of some sort.  We think the silithid use the crystal as some sort of hive-wide attunement device.  As for where this crystal might be, I'd say try the hatcheries inside the hive.\n\nUsing the lure on the crystal should roust out the queen, but be warned - she will probably be protected by several guards.  Take out the queen and remove her brain.  As icky as that sounds, we desperately need to study it.  Good luck, Ewwor!"] = {
		[1] = 4507,
	},
	["Divino-matic Rod:47:Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.:Sergeant Bly stole from me!  He said he'd only borrow it, but he stole my cherished divino-matic rod!!  Without that rod how will I know where to dig new water holes??\n\nFind Bly and bring me my rod!  I heard he led his band of ill-reputed adventurers to go treasure hunting in Zul'Farrak to the west.  I bet you'll find him there.\n\nLet's hope the trolls took care of him, because if you have to fight him for the rod then you're in for a serious fight."] = {
		[1] = 2768,
	},
	["Gerenzo Wrenchwhistle:27:Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.:I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.\n\nNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.\n\nIf you kill him for me, I'll make it worth your while!"] = {
		[1] = 1096,
	},
	["Raene's Cleansing:28:Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.:The final piece of the rod was given to the druids of Dor'danil for safekeeping. I have no idea where they hid it. I'm sorry I can't help you more than that.\n\nAll I can tell you is to follow the road that leads towards the Barrens. The druids took shelter to the east of that road, but they won't be of much help to you: they were killed recently... it's something I don't like to think about much.\n\nWhen you find the final piece, bring it to me and I will help you reconstruct the rod."] = {
		[1] = 1027,
	},
	["Akiris by the Bundle:43:Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.:You looking fer work, Ewwor? I might have some if you're up for a little challenge.\n\nI got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed. Not too sure what it's for, but he pays well for bundles of the stuff.\n\nYa bring me ten stalks of the stuff, and we'll have business to do. The naga were last seen along the beach to the north of here."] = {
		[1] = 617,
	},
	["Crystals of Power:53:Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.:I'm sure you've noticed 'em, Ewwor. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them. I've been doing experiments here with them for a while, but I can't seem to find anything. Well, I haven't yet, anyway.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?"] = {
		[1] = 4284,
	},
	["Tiara of the Deep:46:Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.:Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep.  And not only was it pretty--it held great power for those with the knowledge to use it.\n\nSo when word of the tiara reached the Hydromancer Velratha, she had to have it.  She sent agents to my home and they stole it while I was away.  The thieves!\n\nI want my tiara back!  Go to Zul'Farrak, the troll city in Tanaris, find Velratha and wrench the tiara from her.  Return it to me and you'll earn my favor."] = {
		[1] = 2846,
	},
	["The Missing Courier:43:Locate the courier's boat somewhere along the coast of Feralas.:It's been about a week since Raschal, the courier, set out for Thalanaar.  He knows Feralas well; he's been with us since General Feathermoon led the expeditionary forces here.  I know his plan was to take a row boat down the coast and try and traverse across southern Feralas to avoid the Horde camp.\n\nI couldn't find his boat, but maybe you can.  Maybe it is hidden, or maybe it was sunk.  Regardless, it might hold a clue as to where he is.  If you uncover something, please let me know."] = {
		[1] = 4125,
	},
	["Gem Extraction:1:Gather 100 gem samples by mining.:Gem extraction is an art form, requiring a keen eye and a delicate hand. Your task is to mine and gather 100 gem samples. This will not only test your mining prowess but also your patience and attention to detail. The gems you seek are rare and valuable, so approach this task with the respect it deserves."] = {
		[1] = "Gem Extraction",
	},
	["The Sunken Temple:51:Find Marvon Rivetseeker in Tanaris.:I have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. Much like Troyas and I, he has studied many ancient areas of the world. He was last known to have left his home in Ratchet to study the troll ruins in Tanaris.\n\nGood luck finding him; he hasn't been heard from in some time."] = {
		[1] = 3445,
	},
	["Chasing A-Me 01:53:Find A-Me 01 in Un'Goro Crater.:Unfortunately, something's happened to one of my greatest inventions. You've seen mechanical squirrels, yes? Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has scrying gems for eyes so I could see everything she saw. She made it to Fungal Rock--the apes' lair--just east of here, and that's when I lost contact. The last thing I saw was one of their alpha males rushing up to say hello to her!\n\nCan you help me find her?"] = {
		[1] = 4243,
	},
	["Bookie Herod:35:Find Bookie Herod's Records.:If Kurzen knows Thorsen's secret, then we have a spy in our midst.  We must determine how the secret was leaked!\n\nThorsen's contact within Kurzen's camp was Bookie Herod.  Herod is Kurzen's logistics officer and knows everything about the running of Kurzen's Compound.  If you can get Herod's notes or records, maybe we can find out how Thorsen was discovered.\n\nWhen we were still with Kurzen, Bookie's office was on the top floor of the camp's only two-story house.  His records are probably still there."] = {
		[1] = 200,
	},
	["Skullsplitter Tusks:42:Acquire 18 Skullsplitter Tusks and return them to Kebok.:It's expensive and hard to kill enough tigers to support the export of tiger fangs to the islands in the South Seas. Luckily, we've developed a technique that allows us to take mundane horn-like objects and turn them into undetectable forgeries.\n\nThe closest match we've found, amazingly, are the tusks of the Skullsplitter trolls.\n\nHey, before you say anything, what the buyer doesn't know doesn't hurt them, am I right? Bring me a large number of them so we can get to work on the monthly shipment!"] = {
		[1] = 209,
	},
	["Retrieval for Mauren:26:Bring 8 Crystalized Scales to Collin Mauren in Stormwind.:Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co.\n\nWithin the Charred Vale, deep in Stonetalon, there used to be a species of basilisks whose scales, when ground to dust, made a wonderful reagent for some spells I've created.\n\nIf those basilisks still live, I would love to have a few of their scales.\n\nTake your time, it is no rush, but I can pay well."] = {
		[1] = 1078,
	},
	["Lieutenant Paval Reethe:40:Bring Reethe's Badge to Captain Garran Vimes in Theramore.:A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\"."] = {
		[1] = 1252,
	},
	["The Woodpaw Gnolls:44:Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.:Our \"friends\" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred.  Still, they're the best place to start looking.\n\nI wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned.  I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them."] = {
		[1] = 4131,
	},
	["The Bloodsail Buccaneers:45:Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.:Blast the nerve of Firallon!  He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us.\n\nThe Bloodsail Buccaneers will pay for their carelessness.  Now that we know their plan of attack, we can counter before they know what hit them.\n\nBut why send the entire fleet to do the work of one brave adventuring party?  Ewwor, take some of your most skilled comrades out to Firallon's landing spot and assassinate the Bloodsail leadership.  Their fleet will sink soon after...."] = {
		[1] = 608,
	},
	["Tiger Mastery:33:Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers.:You are learning, druid.  Let us test your skills with the mature cats now. Kill 10 Stranglethorn Tigers this time out."] = {
		[1] = 186,
	},
	["\"Pretty Boy\" Duncan:39:Get Catelyn's dagger from \"Pretty Boy\" Duncan.:My FATHER sent you? I'd have thought that old codger would have given up on me by now.\n\nIt wasn't really his fault I ran off, he just shouldn't have expected I'd be willing to live a boring life, reading over musty books and associating with grey-haired, stiff-backed, stuffy mages!\n\nIf you need my dagger, you'll have to get it back from \"Pretty Boy\" Duncan, one of the Bloodsail Buccaneers. Put something 'tween his shoulders and I'm sure he'll give it up."] = {
		[1] = 610,
	},
	["Panther Mastery:31:Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers.:If you want to be a part of the hunt with this crack group Hemet has assembled, you're going to need to prove yourself an able panther hunter.  We'll start you out easy -- don't you worry.  Let's see you kill 10 young panthers to start.\n\nTracking them down is only half the challenge..."] = {
		[1] = 190,
	},
	["Find OOX-22/FE!:45:Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.:You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\""] = {
		[1] = 2766,
	},
	["Krazek's Cookery:37:Bring Krazek's Crock Pot to Krazek the goblin.:I do most of the cooking at the camp.  And it used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant in Booty Bay.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek."] = {
		[1] = 210,
	},
}
